var calc_output = [];

var sex = parseFloat(sex);
var age = parseFloat(age);
var smoker = parseFloat(smoker);
var sbp = parseFloat(sbp);
var diabetes = parseFloat(diabetes);

if (UOMSYSTEM == true) {
    var tc = parseFloat(tc)*0.02586;
    var hdl = parseFloat(hdl)*0.02586;
} else if (UOMSYSTEM == false) {
    var tc = parseFloat(tc);
    var hdl = parseFloat(hdl);
}

var age_diab = parseFloat(age_diab);
var a1c = parseFloat(a1c);
var egfr = parseFloat(egfr);
var region = parseFloat(region);

var cage = (age - 60)/5;
var csbp = (sbp - 120)/20;
var ctc = tc - 6;
var chdl = (hdl - 1.3)/0.5;
var smoke_age = smoking*cage;
var sbp_age = csbp*cage;
var diabetes_age = diabetes*cage;
var tc_age = ctc*cage;
var hdl_age = chdl*cage;

if (diabetes == 1) {
    var cagediab = (age_diab - 50)/5;
} else {
    var cagediab = 0;
}

var ca1c = (a1c - 31)/9.34;
var cegfr = (Math.log(egfr) - 4.5)/0.15;
var cegfr_sq = Math.pow(cegfr, 2);
var a1c_age = ca1c*cage;
var egfr_age = cegfr*cage;

var x;
var risk_10;

if (sex == 0) {
    x = 0.5368*cage + 0.4774*smoking + 0.1322*csbp + 0.6457*diabetes + 0.1102*ctc + -0.1087*chdl + -0.0672*smoke_age + -0.0268*sbp_age + -0.0983*diabetes_age + -0.0181*tc_age + 0.0095*hdl_age + -0.0998*cagediab + 0.0955*ca1c + -0.0591*cegfr + 0.0058*cegfr_sq + -0.0134*a1c_age + 0.0115*egfr_age;
    risk_10 = 1 - Math.pow(0.9605, Math.exp(x));
} else {
    x = 0.6624*cage + 0.6139*smoking + 0.1421*csbp + 0.8096*diabetes + 0.1127*ctc + -0.1568*chdl + -0.1122*smoke_age + -0.0167*sbp_age + -0.1272*diabetes_age + -0.02*tc_age + 0.0186*hdl_age + -0.1180*cagediab + 0.1173*ca1c + -0.0640*cegfr + 0.0062*cegfr_sq + -0.0196*a1c_age + 0.0169*egfr_age;
    risk_10 = 1 - Math.pow(0.9776, Math.exp(x));
}

var scale1;
var scale2;
if (region == 1) {
    if (sex == 0) {
        scale1 = -0.5699;
        scale2 = 0.7476;
    } else {
        scale1 = -0.7380;
        scale2 = 0.7019;
    }
} else if (region == 2) {
    if (sex == 0) {
        scale1 = -0.1565;
        scale2 = 0.8009;
    } else {
        scale1 = -0.3143;
        scale2 = 0.7701;
    }
} else if (region == 3) {
    if (sex == 0) {
        scale1 = 0.3207;
        scale2 = 0.9360;
    } else {
        scale1 = 0.5710;
        scale2 = 0.9369;
    }
} else if (region == 4) {
    if (sex == 0) {
        scale1 = 0.5836;
        scale2 = 0.8294;
    } else {
        scale1 = 0.9412;
        scale2 = 0.8329;
    }
}

var c_risk = [1 - Math.exp(-Math.exp(scale1 + scale2*Math.log(-Math.log(1 - risk_10))))]*100

calc_output.push({
    name: 'mini',
    value: c_risk.toFixed(1),
    value_text: '%',
    message: '10-year risk of CVD'
});  
calc_output.push({
    name: '10510_SCORE2-Diabetes_result',
    value: c_risk.toFixed(1),
    value_text: '%',
    message: '10-year risk of CVD'
});
